class MiniPromise {
  constructor() { this.reactions = []; this.settled = false; }
  then(handler) { this.reactions.push(handler); return this; }
  settle(value) {
    this.settled = true;
    const log = [];
    // BUG: drains the reaction list from the end -> reverse (LIFO) order.
    while (this.reactions.length) {
      const r = this.reactions.pop();
      log.push(r(value));
    }
    return log;
  }
}

