function withTimeout(task, ms) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('timeout')), ms);
    // task() returns a Promise<T>
    resolve(task().then((v) => {
      clearTimeout(timer);
      return v;
    }));
  });
}

// usage
const data = await withTimeout(() => fetchRow(id), 2000);
